package rbtree;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

/** TEMPORARY: randomized red-black invariant checker. Not part of the package. */
public class _TempValidator {

    static Node<?> rootOf(RedBlackTree<?> t) throws Exception {
        Field f = RedBlackTree.class.getDeclaredField("root");
        f.setAccessible(true);
        return (Node<?>) f.get(t);
    }

    // returns black-height (counting null leaves as black); throws on violation
    @SuppressWarnings({"unchecked", "rawtypes"})
    static int check(Node node, Comparable low, Comparable high) {
        if (node == null) {
            return 1;
        }
        if (low != null && node.data.compareTo(low) <= 0) {
            throw new RuntimeException("BST order violated (left): " + node.data);
        }
        if (high != null && node.data.compareTo(high) >= 0) {
            throw new RuntimeException("BST order violated (right): " + node.data);
        }
        if (node.color == Color.RED) {
            if (isRed(node.left) || isRed(node.right)) {
                throw new RuntimeException("red-red violation at " + node.data);
            }
        }
        if (node.left != null && node.left.parent != node) {
            throw new RuntimeException("bad parent ptr (left) at " + node.data);
        }
        if (node.right != null && node.right.parent != node) {
            throw new RuntimeException("bad parent ptr (right) at " + node.data);
        }
        int lh = check(node.left, low, node.data);
        int rh = check(node.right, node.data, high);
        if (lh != rh) {
            throw new RuntimeException("black-height mismatch at " + node.data + ": " + lh + " vs " + rh);
        }
        return lh + (node.color == Color.BLACK ? 1 : 0);
    }

    static boolean isRed(Node<?> n) {
        return n != null && n.color == Color.RED;
    }

    public static void main(String[] args) throws Exception {
        Random rnd = new Random(12345);
        int trials = 2000;
        int maxN = 60;
        for (int t = 0; t < trials; t++) {
            int n = 1 + rnd.nextInt(maxN);
            List<Integer> vals = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                vals.add(rnd.nextInt(200));
            }
            Collections.shuffle(vals, rnd);
            RedBlackTree<Integer> tree = new RedBlackTree<>();
            for (int v : vals) {
